<template>
  <div class="resource-media-page home-page">
    <HomeSiteNav />
    <main class="resource-media-main home-main">
      <section class="resource-media-section" aria-labelledby="resource-media-title">
        <div class="section-grid resource-media-heading"><div class="section-title-column"><p class="eyebrow">Resource Media</p><h1 id="resource-media-title">媒体<br />库</h1></div><div class="section-copy-column"><p class="lead-copy">集中查看资源封面，确认图片关联关系，并清理未被资源引用的上传对象。</p><router-link class="resource-media-back" to="/manage/resources">← 返回资源管理</router-link></div></div>
        <form v-if="!authenticated" class="resource-media-login" @submit.prevent="login"><label><span>教师管理口令</span><input v-model="password" type="password" autocomplete="current-password" required /></label><button type="submit" :disabled="busy">{{ busy ? '验证中……' : '进入媒体库' }}</button><p v-if="authError" class="resource-media-message is-error" role="alert">{{ authError }}</p></form>
        <template v-else>
          <div class="resource-media-toolbar"><span>已登录教师管理</span><div><router-link to="/manage/resources">资源管理 →</router-link><button type="button" :disabled="busy" @click="loadMedia">刷新数据</button><button type="button" @click="logout">退出</button></div></div>
          <header class="resource-media-library-heading"><div><p class="eyebrow">01 · Library</p><h2>封面对象</h2></div><div class="resource-media-filters" aria-label="媒体状态"><button v-for="option in filterOptions" :key="option.value" type="button" :class="{ 'is-active': filter === option.value }" @click="filter = option.value">{{ option.label }}（{{ countFor(option.value) }}）</button></div></header>
          <div v-if="filteredMedia.length" class="resource-media-list" role="list"><article v-for="item in filteredMedia" :key="item.key" class="resource-media-row" role="listitem"><div class="resource-media-preview"><img v-if="item.kind === 'linked'" :src="item.url" :alt="item.resourceTitle ? `${item.resourceTitle} 封面` : '已关联封面'" loading="lazy" /><span v-else aria-hidden="true">无预览</span></div><div class="resource-media-info"><strong>{{ item.resourceTitle || '未关联资源' }}</strong><span>{{ item.resourceType ? typeLabel(item.resourceType) : '孤儿对象' }} · {{ formatImageBytes(item.size) }}<template v-if="item.width"> · {{ item.width }} × {{ item.height }} px</template></span><span v-if="item.resourceId">资源 ID：{{ item.resourceId }}</span><code>{{ item.key }}</code></div><div class="resource-media-actions"><router-link v-if="item.resourceId" to="/manage/resources">查看资源</router-link><button v-if="item.kind === 'orphan'" type="button" :disabled="busy" @click="removeOrphan(item)">删除孤儿对象</button><span v-else class="resource-media-linked">已关联</span></div></article></div><p v-else class="resource-media-empty" role="status">当前筛选下暂无图片对象。</p>
          <p v-if="actionMessage" class="resource-media-message" role="status">{{ actionMessage }}</p><p v-if="actionError" class="resource-media-message is-error" role="alert">{{ actionError }}</p>
        </template>
      </section>
    </main>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import HomeSiteNav from '../components/navigation/HomeSiteNav.vue'
import { useAuthSession } from '../composables/useAuthSession.js'
import { adminLogin, adminLogout, deleteAdminResourceMedia, getAdminResourceMedia } from '../services/courseState.js'
import { formatImageBytes } from '../utils/compressResourceImage.js'

const filterOptions = [{ value: 'all', label: '全部' }, { value: 'linked', label: '已关联' }, { value: 'orphan', label: '孤儿对象' }]
const typeLabels = { article: '文章', video: '视频', website: '网页', tool: '工具' }
const { isTeacher: authenticated, initialize: initializeAuth, refresh: refreshAuth, clearTeacher } = useAuthSession()
const password = ref(''); const authError = ref(''); const actionError = ref(''); const actionMessage = ref(''); const busy = ref(false); const filter = ref('all'); const media = ref([])
const filteredMedia = computed(() => filter.value === 'all' ? media.value : media.value.filter((item) => item.kind === filter.value))
const countFor = (value) => value === 'all' ? media.value.length : media.value.filter((item) => item.kind === value).length
const typeLabel = (value) => typeLabels[value] || value
const loadMedia = async () => { actionError.value = ''; try { const payload = await getAdminResourceMedia(); media.value = payload.media || [] } catch (cause) { actionError.value = cause.message || '媒体库读取失败，请重试' } }
const login = async () => { busy.value = true; authError.value = ''; try { await adminLogin(password.value); password.value = ''; await refreshAuth(); await loadMedia() } catch (cause) { authError.value = cause.message || '登录失败，请重试' } finally { busy.value = false } }
const logout = async () => { await adminLogout().catch(() => {}); clearTeacher(); media.value = [] }
const removeOrphan = async (item) => { if (!window.confirm('确认删除这个未关联的图片对象吗？删除后无法恢复。')) return; busy.value = true; actionError.value = ''; actionMessage.value = ''; try { await deleteAdminResourceMedia(item.key); media.value = media.value.filter((entry) => entry.key !== item.key); actionMessage.value = '孤儿对象已删除' } catch (cause) { actionError.value = cause.message || '图片对象删除失败，请重试' } finally { busy.value = false } }
onMounted(async () => { await initializeAuth(); if (authenticated.value) await loadMedia() })
</script>

<style scoped>
.resource-media-page{min-height:100vh;color:var(--home-ink);background:var(--home-paper)}.resource-media-page>.site-nav{margin-inline:clamp(3.5rem,4vw,4.5rem);padding-top:clamp(1.5rem,4vh,3rem)}.resource-media-main{padding:2rem clamp(1rem,4vw,4rem) 5rem}.resource-media-section{max-width:1240px;margin:0 auto}.resource-media-heading{margin-bottom:3rem}.resource-media-back{display:inline-flex;min-height:44px;align-items:center;margin-top:1.5rem;color:var(--home-ink);font-size:.78rem;font-weight:700;text-decoration:none}.resource-media-login{display:flex;flex-wrap:wrap;align-items:end;gap:.8rem;max-width:32rem;padding:1.25rem 0;border-block:1px solid var(--home-rule)}.resource-media-login label{display:grid;flex:1 1 15rem;gap:.35rem;color:var(--home-muted);font-size:.72rem}.resource-media-login input{width:100%;min-height:44px;padding:.4rem .6rem;border:1px solid var(--home-ink);border-radius:0;background:var(--home-paper);font:inherit}.resource-media-login button,.resource-media-toolbar button,.resource-media-toolbar a,.resource-media-filters button,.resource-media-actions button,.resource-media-actions a{display:inline-flex;min-height:44px;align-items:center;padding:.4rem .75rem;border:1px solid var(--home-ink);border-radius:0;color:var(--home-ink);background:transparent;font:inherit;font-size:.75rem;text-decoration:none;cursor:pointer}.resource-media-login button{color:var(--home-paper);background:var(--home-ink)}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--accent-orange);outline-offset:2px}.resource-media-toolbar,.resource-media-library-heading{display:flex;align-items:end;justify-content:space-between;gap:1rem}.resource-media-toolbar{padding:.8rem 0;border-block:1px solid var(--home-rule);font-size:.8rem}.resource-media-toolbar div,.resource-media-filters{display:flex;flex-wrap:wrap;gap:.4rem}.resource-media-library-heading{margin-top:3rem;margin-bottom:1rem}.resource-media-library-heading h2{margin-top:.35rem;font-size:clamp(1.3rem,2.4vw,2rem)}.resource-media-filters button.is-active,.resource-media-filters button:hover,.resource-media-filters button:focus-visible{color:var(--home-paper);background:var(--home-ink)}.resource-media-list{border-top:1px solid var(--home-rule)}.resource-media-row{display:grid;grid-template-columns:8rem minmax(0,1fr) auto;align-items:center;gap:1rem;padding:.85rem 0;border-bottom:1px solid var(--home-rule)}.resource-media-preview{width:8rem;aspect-ratio:16/10;background:#f2f2ee}.resource-media-preview img{display:block;width:100%;height:100%;object-fit:cover;border:1px solid var(--home-ink)}.resource-media-info{display:grid;gap:.25rem;min-width:0}.resource-media-info strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.resource-media-info span,.resource-media-info code,.resource-media-linked{color:var(--home-muted);font-size:.68rem}.resource-media-info code{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.resource-media-actions{display:flex;flex-wrap:wrap;justify-content:end;gap:.4rem}.resource-media-actions button{color:#a32f22;border-color:#a32f22}.resource-media-empty{padding:2rem 0;border-top:1px solid var(--home-rule);color:var(--home-muted);font-size:.82rem}.resource-media-message{margin-top:1rem;color:var(--home-muted);font-size:.78rem}.resource-media-message.is-error{color:#a32f22}@media(max-width:767px){.resource-media-page>.site-nav{width:auto;margin-inline:1rem;padding-top:2.5rem}.resource-media-main{padding-inline:1rem}.resource-media-toolbar,.resource-media-library-heading{align-items:start;flex-direction:column}.resource-media-filters{width:100%}.resource-media-filters button{flex:1 1 5rem}.resource-media-row{grid-template-columns:5.5rem minmax(0,1fr);gap:.7rem}.resource-media-preview{width:5.5rem}.resource-media-actions{grid-column:1/-1;justify-content:flex-start}.resource-media-info strong{white-space:normal}}
</style>
<style scoped>
.resource-media-preview { display: grid; place-items: center; color: var(--home-muted); font-size: .68rem; }
</style>
